import React from 'react';

export default function TaskCard({ task, onEdit, onDelete, onToggleComplete }) {
  const deadlineText = task.deadline ? new Date(task.deadline).toLocaleString() : 'No deadline';
  const category = task.category || 'Uncategorized';

  return (
    <div className={`p-4 bg-white rounded shadow flex items-start justify-between ${task.completed ? 'opacity-60' : ''}`}>
      <div className="flex-1">
        <div className="flex items-center gap-3">
          <input type="checkbox" checked={task.completed} onChange={onToggleComplete} className="w-4 h-4" />
          <div>
            <h3 className="text-lg font-semibold">{task.title}</h3>
            <div className="text-xs text-gray-500 mt-1">{category} • {deadlineText}</div>
          </div>
          <span className="ml-4 px-2 py-1 text-sm rounded bg-gray-100">{task.priority}</span>
        </div>

        {task.description && <p className="text-sm text-gray-700 mt-2">{task.description}</p>}
      </div>

      <div className="flex flex-col gap-2 ml-4">
        <button onClick={onEdit} className="px-3 py-1 bg-blue-600 text-white rounded text-sm">Edit</button>
        <button onClick={onDelete} className="px-3 py-1 bg-red-500 text-white rounded text-sm">Delete</button>
      </div>
    </div>
  );
}
